    if (camVals[i] == null || tVals[i] == null || isNaN(tVals[i])) continue;
    raw.push({ t: tVals[i], cam: camVals[i], v: statusVals[i] });
  }
  raw.sort(function (a, b) { return a.t - b.t; });

  var state = {};
  var points = [];
