    var totalT = t1 - t0 || 1;
    function xOf(t) { return ((t - t0) / totalT) * W; }
    function yOf(v) { return H - pad2 - (v / maxV) * (H - pad2 * 2); }
    var d = 'M ' + xOf(points[0].t).toFixed(1) + ',' + yOf(points[0].v).toFixed(1);
    for (var pi = 1; pi < points.length; pi++) {
